    /**
     * Disconnects from the database.
     */
    public void disconnect() {
        if (conn != null) {
            try {
                conn.close();
                System.out.println("Disconnected from the database.");
            } catch (SQLException e) {
                System.out.println(e.getMessage());
            }
        }
    }

    /**
     * Injects SQL into the database.
     *
     * @param sql the SQL to inject
     */
    protected void injectSql(String sql) {
        try (var stmt = conn.createStatement()) {
            stmt.executeUpdate(sql);
            System.out.println("Record accessed successfully.");
        } catch (SQLException e) {
            System.out.println(e.getMessage());
        }
    }

    /**
     * Selects data from the database.
     *
     * @param columns the columns to select
     * @param table the table to select from
     * @return an ArrayList of Objects containing the selected data
     */
    public ArrayList<Object> select(String columns, String table) {
        String sql = "SELECT " + columns + " FROM " + table;
        ArrayList<Object> results = new ArrayList<>();
        try (var stmt = conn.createStatement();
             var rs = stmt.executeQuery(sql)) {
            ResultSetMetaData rsmd = rs.getMetaData();
            int columnCount = rsmd.getColumnCount();
            while (rs.next()) {
                for (int i = 1; i <= columnCount; i++) {
                    Object value = rs.getObject(i);
                    results.add(value);
                }
            }
        } catch (SQLException e) {
            System.out.println(e.getMessage());
        }
        return results;
    }

