    /**
     * Creates the database with a Courses table.
     */
    public void createDatabase() {
        // course table
        String sql = """
            CREATE TABLE IF NOT EXISTS Courses (
             id INTEGER PRIMARY KEY AUTOINCREMENT,
             courseTitle TEXT NOT NULL,
             professor TEXT NOT NULL,
             session TEXT NOT NULL,
             startTime TEXT NOT NULL,
             endTime TEXT NOT NULL,
             courseDays TEXT NOT NULL,
             courseDept TEXT NOT NULL,
             courseCode TEXT NOT NULL,
             numSeats INTEGER NOT NULL DEFAULT 2,
             numRegistered INTEGER NOT NULL DEFAULT 0
            );""";
        injectSql(sql);

        // student table
        sql = """
            CREATE TABLE IF NOT EXISTS Student (
             id INTEGER PRIMARY KEY,
             name TEXT NOT NULL,
             major TEXT NOT NULL,
             minor TEXT,
             username TEXT UNIQUE NOT NULL,
             password TEXT NOT NULL
            );""";
        injectSql(sql);

        // schedule table
        sql = """
            CREATE TABLE IF NOT EXISTS Schedule (
             id INTEGER PRIMARY KEY AUTOINCREMENT,
             scheduleTitle TEXT NOT NULL,
             student INTEGER,
             FOREIGN KEY (student) REFERENCES Student(id)
            );""";
        injectSql(sql);

        // schedule course table
        sql = """
            CREATE TABLE IF NOT EXISTS ScheduleCourses (
             id INTEGER PRIMARY KEY AUTOINCREMENT,
             schedule INTEGER,
             course INTEGER,
             FOREIGN KEY (schedule) REFERENCES Schedule(id),
             FOREIGN KEY (course) REFERENCES Courses(id)
            );""";
        injectSql(sql);

        // Professors table
        sql = """
             CREATE TABLE IF NOT EXISTS Professors (
             id INTEGER PRIMARY KEY AUTOINCREMENT,
             score INTEGER NOT NULL,
             professorName TEXT NOT NULL,
             department TEXT NOT NULL
             );""";
        injectSql(sql);
    }

